import type { Coordinates } from './draw'

export type { Coordinates }

/** Slot coordinates are generated by scripts/generateWindowsCoordinates.ts at build time. */
export async function loadCoordinates(): Promise<Coordinates> {
  const response = await fetch('windows/coordinates.json')
  // The JSON is generated by our own build step; the cast documents the parse boundary.
  return (await response.json()) as Coordinates
}
